// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Optional: max_age_minutes (default 15) ---
const maxAgeMinutes = body.max_age_minutes || 15;

// --- Optional: dry_run (default false) ---
const dryRun = body.dry_run === true;

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: String(body.discord_user_id),
    max_age_minutes: maxAgeMinutes,
    dry_run: dryRun,
    project_id: projectId
  }
};

// ============================================
// FILTER STATS FOR USER & PREPARE CLEANUP
// ============================================

const stats = $input.first().json;
const userData = $('Validate Input').first().json.data;
const userId = userData.discord_user_id;

// --- Check API errors ---
if (!stats.success) {
  return {
    error: true,
    error_code: 'STATS_API_ERROR',
    message: stats.error?.message || 'Erreur lors de la récupération des stats'
  };
}

// --- Get user's job count ---
const userJobCount = stats.jobs_by_user?.[userId] || 0;

// --- Return filtered stats ---
return {
  error: false,
  user_stats: {
    discord_user_id: userId,
    total_jobs: userJobCount,
    zombie_jobs_global: stats.zombie_jobs || 0
  },
  global_stats: {
    total_jobs: stats.total_jobs,
    active_jobs: stats.active_jobs,
    zombie_jobs: stats.zombie_jobs,
    jobs_by_status: stats.jobs_by_status
  },
  should_cleanup: stats.zombie_jobs > 0,
  dry_run: userData.dry_run,
  max_age_minutes: userData.max_age_minutes,
  project_id: userData.project_id
};

// ============================================
// PROCESS CLEANUP & CHECK REFUND
// ============================================

const cleanupResult = $input.first().json;
const statsData = $('Filter User Stats').first().json;

// --- Check API errors ---
if (!cleanupResult.success) {
  return {
    error: true,
    error_code: 'CLEANUP_API_ERROR',
    message: cleanupResult.error?.message || 'Erreur lors du cleanup'
  };
}

// --- Extract refund details ---
const refundDetails = cleanupResult.refund_details || [];

return {
  error: false,
  dry_run: statsData.dry_run,
  stats_before: statsData.global_stats,
  cleaned_count: cleanupResult.cleaned_count || 0,
  refund_required: cleanupResult.refund_required === true && refundDetails.length > 0 && !statsData.dry_run,
  refund_details: refundDetails,
  cleaned_jobs: cleanupResult.cleaned_jobs || []
};

// ============================================
// PREPARE REFUND ITEMS
// ============================================

const data = $input.first().json;
const refundDetails = data.refund_details || [];

// --- Store cleanup data for later ---
const cleanupData = {
  dry_run: data.dry_run,
  stats_before: data.stats_before,
  cleaned_count: data.cleaned_count,
  cleaned_jobs: data.cleaned_jobs
};

// --- Return array of refund items for loop ---
return refundDetails.map(item => ({
  user_id: item.user_id,
  job_id: item.job_id,
  guild_id: item.guild_id,
  filename: item.filename,
  age_minutes: item.age_minutes,
  credits_to_refund: item.credits_to_refund || 1,
  _cleanup_data: cleanupData
}));

