// ============================================
// AGGREGATE REFUND RESULTS
// ============================================

const items = $input.all();
const refundItems = $('Prepare Refund Items').all();

let totalRefunded = 0;
const refundResults = [];

for (let i = 0; i < items.length; i++) {
  const result = items[i].json;
  const original = refundItems[i]?.json || {};

  const success = result.success !== false;
  if (success) {
    totalRefunded += original.credits_to_refund || 1;
  }

  refundResults.push({
    user_id: original.user_id,
    credits: original.credits_to_refund || 1,
    success: success
  });
}

// --- Get cleanup data from first item ---
const cleanupData = refundItems[0]?.json?._cleanup_data || {};

return {
  success: true,
  message: 'Jobs zombies nettoyés avec remboursement',
  dry_run: false,
  stats_before: cleanupData.stats_before,
  cleanup_result: {
    cleaned_count: cleanupData.cleaned_count || 0,
    refunds_processed: refundResults.length,
    total_credits_refunded: totalRefunded,
    refund_details: refundResults
  }
};

// ============================================
// FORMAT NO REFUND RESPONSE
// ============================================

const data = $input.first().json;

return {
  success: true,
  message: data.dry_run ? 'Prévisualisation du nettoyage' : 'Jobs zombies nettoyés (pas de remboursement nécessaire)',
  dry_run: data.dry_run,
  stats_before: data.stats_before,
  cleanup_result: {
    cleaned_count: data.cleaned_count || 0,
    refunds_processed: 0,
    total_credits_refunded: 0
  }
};

// ============================================
// FORMAT NO ZOMBIES RESPONSE
// ============================================

const statsData = $input.first().json;

return {
  success: true,
  message: 'Aucun job zombie à nettoyer',
  user_stats: statsData.user_stats,
  global_stats: statsData.global_stats,
  cleanup_result: {
    cleaned_count: 0,
    refunds_processed: 0,
    total_credits_refunded: 0
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};
